import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Σημειώσεις εκδόσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/release-notes/index.md","filePath":"el/release-notes/index.md"}'),i={name:"el/release-notes/index.md"};function n(s,e,d,l,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="σημειωσεις-εκδοσεων" tabindex="-1">Σημειώσεις εκδόσεων <a class="header-anchor" href="#σημειωσεις-εκδοσεων" aria-label="Permalink to &quot;Σημειώσεις εκδόσεων&quot;">​</a></h1><h2 id="v0-7-11-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" tabindex="-1">v0.7.11 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026) <a class="header-anchor" href="#v0-7-11-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" aria-label="Permalink to &quot;v0.7.11 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026)&quot;">​</a></h2><p>Η έκδοση εισάγει δυνατότητες ενσωματωμένης δημοσίευσης στο Website Studio: διαχείριση φιλοξενίας, επαλήθευση HTTPS, μεταγλώττιση επιλεγμένου σχεδιασμού ιστοσελίδας, προετοιμασία ιδιωτικών αναθεωρήσεων, επαληθευμένα αντίγραφα ασφαλείας και ενημερώσεις ή επαναφορά ιστοσελίδας με εξουσιοδότηση ιδιοκτήτη. Περιλαμβάνει εξουσιοδότηση μίας χρήσης, προστασίες ανάκτησης και συμβατότητα με τον ανεξάρτητο τοπικό χώρο σχεδιασμού.</p><p><strong>Διαθεσιμότητα:</strong> δημοσιευμένη έκδοση λογισμικού μόνο για ελεγχόμενη εγκατάσταση σε δοκιμαστικό περιβάλλον. Δεν αποτελεί απόδειξη ενεργής ιστοσελίδας πελάτη, ζωντανών κρατήσεων ή επεξεργασίας πληρωμών. Δεν περιλαμβάνει μεταβολές σχήματος βάσης δεδομένων ή αλλαγές σε παραγωγικές ιστοσελίδες.</p><h2 id="v0-7-10-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" tabindex="-1">v0.7.10 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026) <a class="header-anchor" href="#v0-7-10-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" aria-label="Permalink to &quot;v0.7.10 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026)&quot;">​</a></h2><p>Οι βελτιώσεις του Website Studio περιλαμβάνουν οπτική επεξεργασία και προεπισκόπηση συσκευών, πολύγλωσσες ιστοσελίδες αναφοράς (αγγλικά, ελληνικά, ιταλικά, γαλλικά, γερμανικά και ισπανικά), επεξεργασία ενοτήτων και ιδιοτήτων, αυτόματη τοπική αποθήκευση προσχεδίων, αντίγραφα ασφαλείας και ανάκτηση, απομόνωση προσχεδίων ανά εταιρεία, φορητά πακέτα <code>.tbsite.json</code> και <code>.tbtheme.json</code> και βελτιωμένη πλοήγηση μεταξύ Website Studio και Theme Manager.</p><p><strong>Διαθεσιμότητα:</strong> δημοσιευμένη έκδοση λογισμικού μόνο για ελεγχόμενη εγκατάσταση σε δοκιμαστικό περιβάλλον. Η δημόσια δημοσίευση ιστοσελίδων, η αποθήκευση στον διακομιστή που απαιτεί τη μεταβολή σχήματος 020, οι ζωντανές πληρωμές και οι εξωτερικές διασυνδέσεις κρατήσεων δεν ενεργοποιήθηκαν από αυτή την έκδοση.</p><h2 id="v0-7-9-—-εκδοση-αναφορας-κωδικα" tabindex="-1">v0.7.9 — έκδοση αναφοράς κώδικα <a class="header-anchor" href="#v0-7-9-—-εκδοση-αναφορας-κωδικα" aria-label="Permalink to &quot;v0.7.9 — έκδοση αναφοράς κώδικα&quot;">​</a></h2><p>Τοπικό Website Studio πολλαπλών σελίδων, προεπισκόπηση συσκευών, φορητά πακέτα και προσχέδια ανά εταιρεία και τρόπο λειτουργίας. Η ενεργοποίηση βάσης δεδομένων και η δημοσίευση αποτελούν ξεχωριστά στάδια αποδοχής.</p><h2 id="v0-7-8-—-ιστορικη-δοκιμαστικη-εκδοση" tabindex="-1">v0.7.8 — ιστορική δοκιμαστική έκδοση <a class="header-anchor" href="#v0-7-8-—-ιστορικη-δοκιμαστικη-εκδοση" aria-label="Permalink to &quot;v0.7.8 — ιστορική δοκιμαστική έκδοση&quot;">​</a></h2><p>Οι καταγραφές περιγράφουν ασφαλή επανάληψη δημιουργίας κράτησης, προαιρετικό email, αποφυγή διπλοεγγραφών και ρητή συγκατάθεση μηνυμάτων. Η δοκιμαστική αποδοχή δεν πιστοποιεί εμπορική διαθεσιμότητα.</p><h2 id="πολιτικη-εκδοσεων" tabindex="-1">Πολιτική εκδόσεων <a class="header-anchor" href="#πολιτικη-εκδοσεων" aria-label="Permalink to &quot;Πολιτική εκδόσεων&quot;">​</a></h2><p>Οι σημειώσεις εκδόσεων καταγράφουν δημοσιευμένες και ιστορικές εκδόσεις, όχι την τρέχουσα εγκατάσταση ή εμπορική διαθεσιμότητα. Οι υπόλοιποι οδηγοί διατηρούν την έκδοση αναφοράς τους μέχρι να ολοκληρωθεί η επαλήθευση για νεότερη έκδοση. Επιβεβαιώστε την πραγματική έκδοση και τις ενεργές δυνατότητες πριν εφαρμόσετε οδηγίες.</p>',13)])])}const _=a(i,[["render",n]]);export{u as __pageData,_ as default};
